SCRIPT = "<script>\n(function(){\n\"use strict\";\nvar el=function(id){return document.getElementById(id)},root=el(\"ofr-start\");if(!root)return;\nvar c=JSON.parse(el(\"ofr-copy\").textContent), bank=el(\"ofr-bank\"),status=el(\"ofr-status\"),goal=el(\"ofr-goal\"),amount=el(\"ofr-amount\"),link=el(\"ofr-compare\");\nfunction event(name,kind){var detail={event:name,kind:kind};document.dispatchEvent(new CustomEvent(\"offrampt-commercial\",{detail:detail}));if(Array.isArray(window.dataLayer))window.dataLayer.push(detail);}\nfunction update(){var b=bank.value,g=goal.value;el(\"ofr-result\").textContent=(b===\"frozen\"?c.frozen:b===\"yes\"?c.banked:c.unbanked)+(b===\"frozen\"?\"\":\" \"+c[g]+(status.value===\"visit\"?\" \"+c.visit:\"\"));link.textContent=b===\"frozen\"?c.resolve:c.compare;link.href=b===\"frozen\"?root.dataset.frozen:\"#calc\";}\n[bank,status,goal].forEach(function(x){x.addEventListener(\"change\",update)});update();\nlink.addEventListener(\"click\",function(){event(\"offrampt_route_open\",bank.value===\"frozen\"?\"resolution\":\"comparison\");if(bank.value===\"frozen\")return;var target=el(\"camt\"),n=Number(amount.value);if(target&&amount.value!==\"\"&&Number.isFinite(n)&&n>=0&&n<=1000000000){target.value=String(n);target.dispatchEvent(new Event(\"input\",{bubbles:true}));}var b=document.querySelector('[data-bank=\"'+(bank.value===\"yes\"?\"yes\":\"no\")+'\"]');if(b)b.click();});\ndocument.addEventListener(\"click\",function(e){var a=e.target.closest(\"a[data-ofr-event], #cbars a\");if(a)event(\"offrampt_commercial_click\",a.dataset.ofrEvent||(a.classList.contains(\"sponsored\")?\"referral\":\"provider\"));});\nfunction num(id,max){var n=Number(el(id).value);return Number.isFinite(n)?Math.min(max,Math.max(0,n)):0;}\nfunction fmt(n){return Math.round(n).toLocaleString(document.documentElement.lang===\"th\"?\"th-TH\":\"en-US\");}\nfunction money(){var m=num(\"ofr-month\",1e9),y=num(\"ofr-years\",100),a=num(\"ofr-fee-a\",100),b=num(\"ofr-fee-b\",100),x=m*12*y*a/100,z=m*12*y*b/100;el(\"ofr-fee-out\").textContent=\"฿\"+fmt(Math.abs(x-z));el(\"ofr-fee-meter\").style.width=(Math.max(x,z)>0?100*Math.abs(x-z)/Math.max(x,z):0)+\"%\";}\nfunction boat(){var m=num(\"ofr-expenses\",1e9),n=num(\"ofr-backup\",1e9);var d=m>0?30*n/m:null;el(\"ofr-boat-out\").textContent=d===null?\"—\":fmt(Math.floor(d));el(\"ofr-boat-meter\").style.width=(d===null?0:Math.min(100,d/90*100))+\"%\";}\nfunction network(){var h=el(\"ofr-node-0\").checked,t=el(\"ofr-node-1\").checked,p=el(\"ofr-node-2\").checked,o=el(\"ofr-node-3\").checked,paths=[h&&t&&o,t&&o,p&&o];paths.forEach(function(x,i){el(\"ofr-path-\"+i).dataset.up=String(x)});var n=paths.filter(Boolean).length;el(\"ofr-network-out\").textContent=n?n+\"/3\":c.noPath;}\n[\"ofr-month\",\"ofr-years\",\"ofr-fee-a\",\"ofr-fee-b\"].forEach(function(i){el(i).addEventListener(\"input\",money)});[\"ofr-expenses\",\"ofr-backup\"].forEach(function(i){el(i).addEventListener(\"input\",boat)});for(var i=0;i<4;i++)el(\"ofr-node-\"+i).addEventListener(\"change\",network);money();boat();network();\n})();\n</script>"


# Hongdam service ids and the price each card shows when hongdam.net/api/services cannot be read at build.
PRICE_FALLBACK = {"bank-account": 4000, "thai-plan": 2000, "crypto-check": 3000}


def render(lang, base, part, prices=None, today=""):
    s = CONTENT[lang][part].replace('__BASE__', base).replace('__DATE__', today)
    for k, v in PRICE_FALLBACK.items():
        s = s.replace(f'__P_{k}__', f'฿{(prices or {}).get(k) or v:,}')
    return s
